sys_script_include.script:
var SAMLUtils = Class.create();
SAMLUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    getLicensingMetric: function() {
        var entitlementId = this.getParameter('sysparm_entitlement_id');
        if (!entitlementId) return '';

        var ent = new GlideRecord('x_1970512_softwa_0_entitlement');
        if (ent.get(entitlementId)) {
            var productId = ent.getValue('product');
            if (productId) {
                var prod = new GlideRecord('x_1970512_softwa_0_product_catalog');
                if (prod.get(productId)) {
                    return prod.getValue('licensing_metric') || '';
                }
            }
        }
        return '';
    },
    type: 'SAMLUtils'
});
